auto capture=[&](const std::string& name){auto c=display->render();std::ofstream out(dir+"/lim-"+name+".pgm",std::ios::binary);out<<"P5\n128 64\n255\n";out.write(reinterpret_cast<char*>(c.pixels),128*64);};
bool applied=true,previews=true;int appliedCount=0,previewCount=0;
for(int track=0;track<2;++track)for(int field=0;field<6;++field){int id=M::accumScreenParam(track,field);auto* q=m->getParamQuantity(id);
    for(int v=int(q->getMinValue());v<=int(q->getMaxValue());++v){clean(track,field);q->setValue(float(v));auto before=raw();applied &= pixels(track,field,v,false) && raw()==before && !APP->history->actionIndex;++appliedCount;if(v==int(q->getMaxValue()))capture("t"+std::to_string(track)+"-f"+std::to_string(field)+"-max");}
    for(auto* control:{encoder,static_cast<HardwareControl*>(display)})for(int v=int(q->getMinValue())+1;v<=int(q->getMaxValue());++v){clean(track,field);m->params[M::ENC_CONFIRM].setValue(1);q->setValue(q->getMinValue());auto before=raw();drag(control,-22.f*(v-q->getMinValue()));previews &= pendingConfirmation(m) && m->uiDraftParam==id && m->uiValue(id)==v && raw()==before && !APP->history->actionIndex && pixels(track,field,v,true);++previewCount;if(control==encoder && v==int(q->getMaxValue()))capture("t"+std::to_string(track)+"-f"+std::to_string(field)+"-pending");}
}
check(applied,std::to_string(appliedCount)+" applied LIM pixel states show all six fields, signed limits, three reference rows and track footer");check(previews,std::to_string(previewCount)+" actual pending LIM pixel states retain preview isolation and show inline question marks with the confirmation footer");check(spacing,"all LIM labels and values including pending markers fit without abbreviation");
bool nav=true,edits=true;int navCount=0,editCount=0;
for(int track=0;track<2;++track)for(int field=0;field<6;++field)for(auto* control:{encoder,static_cast<HardwareControl*>(display)}){clean(track,field);auto before=raw();click(control);nav &= m->uiField.load()==(field+1)%6 && raw()==before && !APP->history->actionIndex;++navCount;
    for(int confirm=0;confirm<2;++confirm){clean(track,field);int id=M::accumScreenParam(track,field);auto* q=m->getParamQuantity(id);q->setValue(q->getMinValue());m->params[M::ENC_CONFIRM].setValue(float(confirm));before=raw();drag(control,confirm?-22.f:-220.f);auto after=before;if(confirm){edits &= pendingConfirmation(m) && raw()==before && !APP->history->actionIndex;click(control);after[id]=q->getMinValue()+1;}else{after[id]=m->params[id].getValue();edits &= after[id]>q->getMinValue() && after[id]<=q->getMaxValue();}edits &= raw()==after && m->uiField.load()==field && !pendingConfirmation(m) && APP->history->actionIndex==1;APP->history->undo();edits &= raw()==before;APP->history->redo();edits &= raw()==after;++editCount;}
}
check(nav,std::to_string(navCount)+" LIM clicks retain six-field cycling without parameter/history changes");check(edits,std::to_string(editCount)+" immediate/confirmed LIM edits retain full-parameter exact Undo/Redo on both controls/tracks");
bool ownedPixels=true,locked=true,menus=true;int ownedCount=0,lockedCount=0;
for(int track=0;track<2;++track)for(int knob=0;knob<2;++knob)for(int field:{2,4})for(int both=0;both<2;++both){
    for(int selected=field/3*3;selected<field/3*3+3;++selected){clean(track,selected);own(track,knob,field,both);auto before=raw();ownedPixels &= pixels(track,selected,m->integer(M::accumScreenParam(track,selected)),false) && raw()==before && !APP->history->actionIndex;capture("t"+std::to_string(track)+"-ctrl"+std::to_string(knob)+"-f"+std::to_string(field)+"-both"+std::to_string(both)+"-selected"+std::to_string(selected));++ownedCount;}
    for(auto* control:{encoder,static_cast<HardwareControl*>(display)}){clean(track,field);own(track,knob,field,both);auto before=raw();drag(control,-220);locked &= raw()==before && m->uiField.load()==field && !APP->history->actionIndex;widget::EventContext ctx;event::DoubleClick dbl;dbl.context=&ctx;control->onDoubleClick(dbl);locked &= raw()==before && !APP->history->actionIndex;click(control);locked &= m->uiField.load()==field+1 && raw()==before && !APP->history->actionIndex;m->uiField.store(field);press(control,GLFW_MOUSE_BUTTON_RIGHT);menus &= seek(APP->scene,[&](widget::Widget* w){auto* label=dynamic_cast<ui::MenuLabel*>(w);return label && label->text=="CTRL "+std::to_string(knob+1);})!=nullptr && raw()==before && !APP->history->actionIndex;closeMenus();++lockedCount;}
}
